import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapWorkoutFullToFront,
  mapWorkoutToFront,
  mapWorkoutType,
} from '../@mappers/workouts.mapper';
import {
  IWorkoutAddDto,
  IWorkoutAddResult,
  IWorkoutFullDTO,
  IWorkoutEditDTO,
  IWorkoutTypeDTO,
} from '../@types/DTO/workouts.dto.types';
import { IWorkout, IWorkoutType, IWorkoutFull } from '../@types/workouts.types';

export interface IWorkoutsCriteria {
  include_trackdata?: any;
  limit?: number;
  offset?: number;
  id_group?: number;
  id_user?: number;
  d1?: string;
  d2?: string;
  d?: string;
  tag?: string;
  y?: string;
  type?: string;
}

export const getWorkouts = async (params: IWorkoutsCriteria): Promise<IWorkout[]> => {
  const res = await get<IWorkoutFullDTO, IWorkoutsCriteria>('/ajax/workouts/list.php', params).then(
    handleApiError,
  );

  return res.map(mapWorkoutToFront);
};
export const getOneWorkout = async (id: number): Promise<IWorkoutFull> => {
  const res = await get<IWorkoutFullDTO>('/ajax/workouts/one.php', { id }).then<IWorkoutFullDTO>(
    handleApiError,
  );

  return mapWorkoutFullToFront(res);
};

export const getWorkoutTypes = async (): Promise<IWorkoutType[]> => {
  const res = await get<IWorkoutTypeDTO[]>('/ajax/workouts/types.php').then(handleApiError);

  return res.map(mapWorkoutType);
};

export const addWorkoutAsync = async (data: IWorkoutAddDto) => {
  return post<IWorkoutAddResult>('/ajax/workouts/add.php', data).then<IWorkoutAddResult>(
    handleApiError,
  );
};

export const editWorkout = async (data: IWorkoutEditDTO) => {
  return post<{ success: boolean }, IWorkoutEditDTO>('/ajax/workouts/edit.php', data).then<{
    success: boolean;
  }>(handleApiError);
};

export const renameWorkoutGroup = (id_workout_group: number, name: string) => {
  return post('/ajax/workouts/rename_workout_group.php', { id: id_workout_group, name });
};
